// Minimal PromoCard renderer
import React from 'react';
export default function PromoCard({card}) {
  if (!card.title || !card.imageUrl) return null;
  return (
    <View style={styles.card}>
      <Image source={{uri: card.imageUrl}} style={styles.image} />
      <Text style={styles.title}>{card.title}</Text>
      {card.subtitle && <Text style={styles.subtitle}>{card.subtitle}</Text>}
      {card.cta && card.cta.action && (
        <Button title={card.cta.label} onPress={()=>{ /* action */ }} />
      )}
    </View>
  );
}
```

