// WatermelonDB POI schema sketch
const poisSchema = tableSchema({
  name: 'pois',
  columns: [
    { name: 'name', type: 'string' },
    { name: 'lat', type: 'number' },
    { name: 'lon', type: 'number' },
    { name: 'last_modified', type: 'number' },
  ],
});

// MarkerLayer sketch (conceptual)
function MarkerLayer({ pois }) {
  const clusters = clusterPoints(pois, 60); // 60px radius
  return clusters.map((c) => (
    <Marker key={c.id} coordinate={c.center} onPress={() => openPOI(c.pois[0].id)}>
      <Callout>{c.count} POIs</Callout>
    </Marker>
  ));
}
```

